function native.info(name)
    local e = NATIVE_CATALOG[tostring(name)]
    if not e then return nil end
    return { addr = e[1], decl = e[2], side = e[3], risk = e[4],
             category = e[5], wrappedBy = e[6] ~= '' and e[6] or nil }
end

function native.catalogStats()
    return { total = 4856, client = 2310, server = 2546 }
end

